const e=`<?xml version="1.0" encoding="utf-8"?>\r
<style xmlns="http://purl.org/net/xbiblio/csl" and="text" class="in-text" demote-non-dropping-particle="never" initialize-with=". " page-range-format="minimal-two" version="1.0">\r
  <!-- This file was generated by the Style Variant Builder <https://github.com/citation-style-language/style-variant-builder>. To contribute changes, modify the template and regenerate variants. -->\r
  <info>\r
    <title>MLA Handbook 9th edition (in-text citations)</title>\r
    <title-short>Modern Language Association (in-text citations)</title-short>\r
    <id>http://www.zotero.org/styles/modern-language-association</id>\r
    <link href="http://www.zotero.org/styles/modern-language-association" rel="self"/>\r
    <link href="https://style.mla.org/" rel="documentation"/>\r
    <link href="https://zotero.org/groups/2205533/collections/L96HMJXY" rel="documentation"/>\r
    <author>\r
      <name>Sebastian Karcher</name>\r
      <uri>https://orcid.org/0000-0001-8249-7388</uri>\r
    </author>\r
    <author>\r
      <name>Andrew Dunning</name>\r
      <uri>https://orcid.org/0000-0003-0464-5036</uri>\r
    </author>\r
    <contributor>\r
      <name>Patrick O'Brien</name>\r
    </contributor>\r
    <category citation-format="author"/>\r
    <category field="generic-base"/>\r
    <category field="humanities"/>\r
    <category field="literature"/>\r
    <summary>MLA source citations, in-text citations system (chapter 6)</summary>\r
    <updated>2026-02-03T00:00:00+00:00</updated>\r
    <rights license="http://creativecommons.org/licenses/by-sa/3.0/">This work is licensed under a Creative Commons Attribution-ShareAlike 3.0 License</rights>\r
  </info>\r
  <locale xml:lang="en">\r
    <date form="text">\r
      <date-part name="day" suffix=" "/>\r
      <date-part form="short" name="month" suffix=" "/>\r
      <date-part name="year"/>\r
    </date>\r
    <terms>\r
      <!-- MLA Appendix 1 -->\r
      <term form="short" name="chapter">\r
        <single>ch.</single>\r
        <multiple>chs.</multiple>\r
      </term>\r
      <term name="collection-editor">\r
        <single>general editor</single>\r
        <multiple>general editors</multiple>\r
      </term>\r
      <term name="editor-translator">\r
        <single>editor and translator</single>\r
        <multiple>editors and translators</multiple>\r
      </term>\r
      <term name="editortranslator">\r
        <single>editor and translator</single>\r
        <multiple>editors and translators</multiple>\r
      </term>\r
      <term form="verb" name="editor-translator">edited and translated by</term>\r
      <term form="verb" name="editortranslator">edited and translated by</term>\r
      <term name="original-work-published">originally published</term>\r
      <term form="short" name="paragraph">\r
        <single>par.</single>\r
        <multiple>pars.</multiple>\r
      </term>\r
      <term form="short" name="version">vers.</term>\r
    </terms>\r
  </locale>\r
  <!-- Contents:\r
\r
       MLA provides the following series of elements for citations:\r
\r
       1. Author (MLA 5.3-22)\r
       2. Title of Source (MLA 5.23-30)\r
       3. Supplemental Element after Title of Source (MLA 5.106-109)\r
          3.1. Contributor (MLA 5.107)\r
          3.2. Original publication date (MLA 5.108)\r
          3.3. Section of a work labeled generically (MLA 5.109)\r
       4. Container 1\r
          4.1. Title of Container (MLA 5.31-37)\r
          4.2. Contributor (MLA 5.38-47)\r
          4.3. Version (MLA 5.48-50)\r
          4.4. Number (MLA 5.51-53)\r
          4.5. Publisher (MLA 5.54-67)\r
          4.6. Publication Date (MLA 5.68-83)\r
          4.7. Location (MLA 5.84-99)\r
       5. Supplemental Element Between Containers (MLA 5.119)\r
       6. Container 2 (MLA 5.102)\r
       7. Supplemental Element at End of Entry (MLA 5.110-118)\r
          7.1. Date of access (MLA 5.111)\r
          7.2. Medium of publication (MLA 5.112)\r
          7.3. Dissertations and theses (MLA 5.113)\r
          7.4. Publication history (MLA 5.114)\r
          7.5. Book series (MLA 5.115)\r
          7.6. Columns, sections, and other recurring titled features (MLA 5.116)\r
          7.7. Multivolume works (MLA 5.117)\r
  -->\r
  <!-- Categories of CSL item types:\r
\r
       Serial\r
       : article-journal article-magazine article-newspaper periodical post-weblog review review-book\r
\r
       Serial or Monographic\r
       : interview paper-conference\r
\r
         Monographic with any of \`collection-editor compiler editor editorial-director\`.\r
         A serial \`paper-conference\` is unpublished if it lacks any of \`issue page supplement-number volume\`.\r
\r
       Monographic\r
       : article book broadcast chapter classic collection dataset document\r
         entry entry-dictionary entry-encyclopedia event figure\r
         graphic manuscript map motion_picture musical_score\r
         pamphlet patent performance personal_communication post report\r
         software song speech standard thesis webpage\r
\r
       Legal\r
       : bill hearing legal_case legislation regulation treaty\r
  -->\r
  <!-- Variable labels -->\r
  <macro name="label-edition-capitalized">\r
    <group delimiter=" ">\r
      <choose>\r
        <if is-numeric="edition">\r
          <number form="ordinal" variable="edition"/>\r
          <label form="short" variable="edition"/>\r
        </if>\r
        <else>\r
          <text text-case="capitalize-first" variable="edition"/>\r
        </else>\r
      </choose>\r
    </group>\r
  </macro>\r
  <macro name="label-issue">\r
    <group delimiter=" ">\r
      <label form="short" variable="issue"/>\r
      <text variable="issue"/>\r
    </group>\r
  </macro>\r
  <macro name="label-locator">\r
    <group delimiter=" ">\r
      <label form="short" variable="locator"/>\r
      <text variable="locator"/>\r
    </group>\r
  </macro>\r
  <macro name="label-number">\r
    <group delimiter=" ">\r
      <choose>\r
        <if type="standard"/>\r
        <else-if is-numeric="number">\r
          <label form="short" variable="number"/>\r
        </else-if>\r
      </choose>\r
      <text variable="number"/>\r
    </group>\r
  </macro>\r
  <macro name="label-number-of-volumes">\r
    <group delimiter=" ">\r
      <text variable="number-of-volumes"/>\r
      <choose>\r
        <if is-numeric="number-of-volumes">\r
          <label form="short" variable="number-of-volumes"/>\r
        </if>\r
      </choose>\r
    </group>\r
  </macro>\r
  <macro name="label-page">\r
    <group delimiter=" ">\r
      <label form="short" variable="page"/>\r
      <text variable="page"/>\r
    </group>\r
  </macro>\r
  <macro name="label-part-number">\r
    <group delimiter=" ">\r
      <choose>\r
        <if is-numeric="part-number">\r
          <!-- TODO: Replace with \`part-number\` label when CSL provides one -->\r
          <text form="short" term="part"/>\r
        </if>\r
      </choose>\r
      <text variable="part-number"/>\r
    </group>\r
  </macro>\r
  <macro name="label-part-number-capitalized">\r
    <group delimiter=" ">\r
      <choose>\r
        <if is-numeric="part-number">\r
          <!-- TODO: Replace with \`part-number\` label when CSL provides one -->\r
          <text form="short" term="part" text-case="capitalize-first"/>\r
        </if>\r
      </choose>\r
      <text text-case="capitalize-first" variable="part-number"/>\r
    </group>\r
  </macro>\r
  <macro name="label-supplement-number">\r
    <group delimiter=" ">\r
      <choose>\r
        <!-- TODO: Replace with \`supplement-number\` label when CSL provides one -->\r
        <if is-numeric="supplement-number">\r
          <text form="short" term="supplement"/>\r
        </if>\r
      </choose>\r
      <text variable="supplement-number"/>\r
    </group>\r
  </macro>\r
  <macro name="label-version">\r
    <group delimiter=" ">\r
      <label variable="version"/>\r
      <text variable="version"/>\r
    </group>\r
  </macro>\r
  <macro name="label-version-capitalized">\r
    <group delimiter=" ">\r
      <label text-case="capitalize-first" variable="version"/>\r
      <text variable="version"/>\r
    </group>\r
  </macro>\r
  <macro name="label-volume">\r
    <group delimiter=" ">\r
      <choose>\r
        <if is-numeric="volume">\r
          <label form="short" variable="volume"/>\r
        </if>\r
      </choose>\r
      <text variable="volume"/>\r
    </group>\r
  </macro>\r
  <macro name="label-volume-capitalized">\r
    <group delimiter=" ">\r
      <choose>\r
        <if is-numeric="volume">\r
          <label form="short" text-case="capitalize-first" variable="volume"/>\r
        </if>\r
      </choose>\r
      <text text-case="capitalize-first" variable="volume"/>\r
    </group>\r
  </macro>\r
  <!-- 1. Author (MLA 5.3-22) -->\r
  <macro name="author">\r
    <names variable="composer">\r
      <name delimiter-precedes-et-al="always" delimiter-precedes-last="always" initialize="false" name-as-sort-order="first"/>\r
      <label prefix=", "/>\r
      <substitute>\r
        <names variable="author"/>\r
        <names variable="guest">\r
          <name delimiter-precedes-et-al="always" delimiter-precedes-last="always" initialize="false" name-as-sort-order="first"/>\r
          <!-- \`guest\` has no label (see MLA 'Interview by podcast host') -->\r
        </names>\r
        <names variable="editor-translator"/>\r
        <names variable="editor"/>\r
        <names variable="translator"/>\r
        <choose>\r
          <if type="standard">\r
            <text variable="authority"/>\r
          </if>\r
        </choose>\r
        <text macro="title"/>\r
      </substitute>\r
    </names>\r
  </macro>\r
  <macro name="author-short">\r
    <group delimiter=", ">\r
      <names variable="composer">\r
        <name form="short" initialize="true"/>\r
        <substitute>\r
          <names variable="author"/>\r
          <names variable="guest"/>\r
          <names variable="editor-translator"/>\r
          <names variable="editor"/>\r
          <names variable="translator"/>\r
          <choose>\r
            <if type="standard">\r
              <text variable="authority"/>\r
            </if>\r
          </choose>\r
          <text macro="title-short"/>\r
        </substitute>\r
      </names>\r
      <choose>\r
        <if disambiguate="true">\r
          <text macro="title-short"/>\r
        </if>\r
      </choose>\r
    </group>\r
  </macro>\r
  <!-- 2. Title of Source (MLA 5.23-30) -->\r
  <macro name="title">\r
    <choose>\r
      <if match="any" type="post webpage">\r
        <!-- print \`container-title\` on \`post\` or \`webpage\` in the same way as \`publisher\` -->\r
        <text macro="title-and-part-filter-review"/>\r
      </if>\r
      <else-if match="any" type="article-journal article-magazine article-newspaper periodical post-weblog review review-book">\r
        <!-- serial types -->\r
        <text macro="title-and-part-filter-review"/>\r
      </else-if>\r
      <else-if match="any" variable="collection-editor compiler editor editorial-director">\r
        <text macro="title-monographic"/>\r
      </else-if>\r
      <else-if match="any" type="interview paper-conference">\r
        <!-- serial types -->\r
        <text macro="title-and-part-filter-review"/>\r
      </else-if>\r
      <else>\r
        <text macro="title-monographic"/>\r
      </else>\r
    </choose>\r
  </macro>\r
  <macro name="title-short">\r
    <choose>\r
      <if match="any" type="review review-book" variable="reviewed-author reviewed-genre reviewed-title">\r
        <!-- If a review has no \`reviewed-title\`, assume that \`title\` contains the title of the reviewed work; the description provides it. -->\r
        <choose>\r
          <if variable="reviewed-genre title">\r
            <!-- Quotes, title case -->\r
            <text form="short" quotes="true" text-case="title" variable="title"/>\r
          </if>\r
          <else-if variable="reviewed-genre reviewed-title title">\r
            <!-- Quotes, title case -->\r
            <text form="short" quotes="true" text-case="title" variable="title"/>\r
          </else-if>\r
          <else>\r
            <text macro="supplemental-generic-label-short"/>\r
          </else>\r
        </choose>\r
      </if>\r
      <else-if variable="title">\r
        <text macro="title-primary-short"/>\r
      </else-if>\r
      <else>\r
        <text macro="supplemental-generic-label-short"/>\r
      </else>\r
    </choose>\r
  </macro>\r
  <!-- Title elements -->\r
  <macro name="title-and-part-filter-review">\r
    <choose>\r
      <if match="any" type="review review-book" variable="reviewed-author reviewed-genre reviewed-title">\r
        <!-- \`title\` is only the review title if there is a separate \`reviewed-genre\` or \`reviewed-title\`; otherwise, it is the title of the reviewed work, printed in the description -->\r
        <choose>\r
          <if match="any" variable="reviewed-genre reviewed-title">\r
            <text macro="title-and-part-title"/>\r
          </if>\r
        </choose>\r
      </if>\r
      <else>\r
        <text macro="title-and-part-title"/>\r
      </else>\r
    </choose>\r
  </macro>\r
  <macro name="title-and-part-title">\r
    <group delimiter=", ">\r
      <text macro="title-primary"/>\r
      <text macro="label-part-number"/>\r
      <text macro="title-part"/>\r
    </group>\r
  </macro>\r
  <macro name="title-monographic">\r
    <!-- For monographic items, assume \`part-number\` and \`part-title\` refer to the book/volume. -->\r
    <choose>\r
      <if variable="container-title">\r
        <text macro="title-primary"/>\r
      </if>\r
      <!-- For monographic items without \`container-title\`, bibliography entries list \`part-title\` or \`volume-title\` first if available -->\r
      <else-if variable="part-title">\r
        <text font-style="italic" text-case="title" variable="part-title"/>\r
      </else-if>\r
      <else-if variable="volume-title">\r
        <text font-style="italic" text-case="title" variable="volume-title"/>\r
      </else-if>\r
      <else>\r
        <text macro="title-primary"/>\r
      </else>\r
    </choose>\r
  </macro>\r
  <macro name="title-part">\r
    <choose>\r
      <if match="any" type="article-journal article-magazine article-newspaper periodical post-weblog review review-book">\r
        <text quotes="true" text-case="title" variable="part-title"/>\r
      </if>\r
      <else-if match="any" variable="collection-editor compiler editor editorial-director">\r
        <!-- monographic types -->\r
        <text font-style="italic" text-case="title" variable="part-title"/>\r
      </else-if>\r
      <else-if match="any" type="interview paper-conference">\r
        <!-- serial types -->\r
        <text quotes="true" text-case="title" variable="part-title"/>\r
      </else-if>\r
      <else>\r
        <!-- monographic types -->\r
        <text font-style="italic" text-case="title" variable="part-title"/>\r
      </else>\r
    </choose>\r
  </macro>\r
  <macro name="title-primary">\r
    <choose>\r
      <if match="any" type="bill collection legislation regulation treaty">\r
        <!-- No italics or quotes, title case -->\r
        <text text-case="title" variable="title"/>\r
      </if>\r
      <else-if type="legal_case">\r
        <!-- Italicized, sentence case -->\r
        <text font-style="italic" variable="title"/>\r
      </else-if>\r
      <else-if match="any" type="book classic graphic hearing map periodical">\r
        <!-- Italicized, title case (regardless of \`container-title\`) -->\r
        <text font-style="italic" text-case="title" variable="title"/>\r
      </else-if>\r
      <else-if type="post">\r
        <!-- Quotes, sentence case -->\r
        <text quotes="true" variable="title"/>\r
      </else-if>\r
      <!-- Other types are formatted based on presence of \`container-title\` -->\r
      <else-if variable="container-title">\r
        <!-- Quotes, title case -->\r
        <text quotes="true" text-case="title" variable="title"/>\r
      </else-if>\r
      <else-if match="any" type="article dataset document interview manuscript paper-conference personal_communication speech">\r
        <!-- Container-like but not necessarily with \`container-title\` -->\r
        <!-- Quotes, title case -->\r
        <text quotes="true" text-case="title" variable="title"/>\r
      </else-if>\r
      <else>\r
        <!-- Italicized, title case (default) -->\r
        <text font-style="italic" text-case="title" variable="title"/>\r
      </else>\r
    </choose>\r
  </macro>\r
  <macro name="title-primary-short">\r
    <choose>\r
      <if match="any" type="bill collection legislation regulation treaty">\r
        <!-- No italics or quotes, title case -->\r
        <text form="short" text-case="title" variable="title"/>\r
      </if>\r
      <else-if type="legal_case">\r
        <!-- Italicized, sentence case -->\r
        <text font-style="italic" form="short" variable="title"/>\r
      </else-if>\r
      <else-if match="any" type="book classic graphic hearing map periodical">\r
        <!-- Italicized, title case (regardless of \`container-title\`) -->\r
        <text font-style="italic" form="short" text-case="title" variable="title"/>\r
      </else-if>\r
      <else-if type="post">\r
        <!-- Quotes, sentence case -->\r
        <text form="short" quotes="true" variable="title"/>\r
      </else-if>\r
      <!-- Other types are formatted based on presence of \`container-title\` -->\r
      <else-if variable="container-title">\r
        <!-- Quotes, title case -->\r
        <text form="short" quotes="true" text-case="title" variable="title"/>\r
      </else-if>\r
      <else-if match="any" type="article dataset document interview manuscript paper-conference personal_communication speech">\r
        <!-- Container-like but not necessarily with \`container-title\` -->\r
        <!-- Quotes, title case -->\r
        <text form="short" quotes="true" text-case="title" variable="title"/>\r
      </else-if>\r
      <else>\r
        <!-- Italicized, title case (default) -->\r
        <text font-style="italic" form="short" text-case="title" variable="title"/>\r
      </else>\r
    </choose>\r
  </macro>\r
  <!-- 3. Supplemental Element after Title of Source (MLA 5.106-109) -->\r
  <macro name="supplemental-element-after-title">\r
    <group delimiter=", ">\r
      <text macro="supplemental-contributor"/>\r
      <text macro="supplemental-original-date"/>\r
      <text macro="supplemental-generic-label"/>\r
    </group>\r
  </macro>\r
  <!-- 3.1. Contributor (MLA 5.107) -->\r
  <macro name="supplemental-contributor">\r
    <names delimiter=", " variable="interviewer">\r
      <label form="verb" suffix=" " text-case="capitalize-first"/>\r
      <name initialize="false"/>\r
    </names>\r
  </macro>\r
  <!-- 3.2. Original publication date (MLA 5.108) -->\r
  <macro name="supplemental-original-date">\r
    <choose>\r
      <if type="personal_communication">\r
        <!-- date and place of composition for letters -->\r
        <text macro="container1-location-event"/>\r
      </if>\r
      <else-if match="any" variable="original-publisher original-publisher-place"/>\r
      <else-if is-uncertain-date="original-date">\r
        <date form="text" prefix="[" suffix="?]" variable="original-date"/>\r
      </else-if>\r
      <else>\r
        <date form="text" variable="original-date"/>\r
      </else>\r
    </choose>\r
  </macro>\r
  <!-- 3.3. Section of a work labeled generically (MLA 5.109) -->\r
  <macro name="supplemental-generic-label">\r
    <choose>\r
      <if match="any" type="review review-book" variable="reviewed-author reviewed-genre reviewed-title">\r
        <text macro="supplemental-generic-label-review"/>\r
      </if>\r
      <else-if type="thesis"/>\r
      <else-if variable="number"/>\r
      <else>\r
        <text text-case="capitalize-first" variable="genre"/>\r
      </else>\r
    </choose>\r
  </macro>\r
  <macro name="supplemental-generic-label-short">\r
    <choose>\r
      <if match="any" type="review review-book" variable="reviewed-author reviewed-genre reviewed-title">\r
        <text macro="supplemental-generic-label-review-short"/>\r
      </if>\r
      <else>\r
        <text form="short" text-case="capitalize-first" variable="genre"/>\r
      </else>\r
    </choose>\r
  </macro>\r
  <!-- Generic label elements -->\r
  <macro name="supplemental-generic-label-review">\r
    <group delimiter=" ">\r
      <choose>\r
        <if variable="reviewed-genre">\r
          <text term="review-of" text-case="capitalize-first"/>\r
          <text variable="reviewed-genre"/>\r
          <choose>\r
            <if match="none" variable="reviewed-title">\r
              <names variable="reviewed-author">\r
                <label form="verb" suffix=" "/>\r
                <name initialize="false"/>\r
              </names>\r
            </if>\r
          </choose>\r
        </if>\r
        <else-if variable="number">\r
          <text term="review-of" text-case="capitalize-first"/>\r
        </else-if>\r
        <!-- If no \`reviewed-genre\`, assume that \`genre\` is entered as 'Review of the book' or similar -->\r
        <else-if variable="genre">\r
          <text text-case="capitalize-first" variable="genre"/>\r
        </else-if>\r
        <else>\r
          <text term="review-of" text-case="capitalize-first"/>\r
        </else>\r
      </choose>\r
      <choose>\r
        <if match="any" variable="reviewed-genre reviewed-title">\r
          <!-- Not possible to distinguish TV series episode from other reviewed works without a reviewed source title -->\r
          <!-- Adapt for \`reviewed-container-title\` or similar if it becomes available -->\r
          <text font-style="italic" text-case="title" variable="reviewed-title"/>\r
        </if>\r
        <else>\r
          <!-- Assume title is title of reviewed work -->\r
          <text font-style="italic" text-case="title" variable="title"/>\r
        </else>\r
      </choose>\r
    </group>\r
    <choose>\r
      <if variable="reviewed-genre reviewed-title title">\r
        <names variable="reviewed-author">\r
          <label form="verb" suffix=" "/>\r
          <name initialize="false"/>\r
        </names>\r
      </if>\r
      <else-if variable="reviewed-genre"/>\r
      <else>\r
        <names variable="reviewed-author">\r
          <label form="verb" suffix=" "/>\r
          <name initialize="false"/>\r
        </names>\r
      </else>\r
    </choose>\r
  </macro>\r
  <macro name="supplemental-generic-label-review-short">\r
    <group delimiter=" ">\r
      <text term="review-of"/>\r
      <choose>\r
        <if match="any" variable="reviewed-genre reviewed-title">\r
          <!-- Not possible to distinguish TV series episode from other reviewed works without a reviewed source title -->\r
          <!-- Adapt for \`reviewed-container-title\` or similar if it becomes available -->\r
          <text font-style="italic" form="short" text-case="title" variable="reviewed-title"/>\r
        </if>\r
        <else>\r
          <!-- Assume title is title of reviewed work -->\r
          <text font-style="italic" form="short" text-case="title" variable="title"/>\r
        </else>\r
      </choose>\r
    </group>\r
  </macro>\r
  <!-- 4. Container 1 -->\r
  <macro name="container1">\r
    <group delimiter=", ">\r
      <text macro="container1-title"/>\r
      <text macro="container1-contributor"/>\r
      <text macro="container1-version"/>\r
      <text macro="container1-number"/>\r
      <text macro="container1-publisher"/>\r
      <text macro="container1-publication-date"/>\r
      <text macro="container1-location"/>\r
    </group>\r
  </macro>\r
  <!-- 4.1. Title of Container (MLA 5.31-37) -->\r
  <macro name="container1-title">\r
    <choose>\r
      <if match="any" type="article-journal article-magazine article-newspaper periodical post-weblog review review-book">\r
        <!-- serial types -->\r
        <text macro="container1-title-serial"/>\r
      </if>\r
      <else-if match="any" variable="collection-editor compiler editor editorial-director">\r
        <!-- monographic types -->\r
        <text macro="container1-title-monographic"/>\r
      </else-if>\r
      <else-if match="any" type="interview paper-conference">\r
        <!-- serial types -->\r
        <text macro="container1-title-serial"/>\r
      </else-if>\r
      <else>\r
        <!-- monographic types -->\r
        <text macro="container1-title-monographic"/>\r
      </else>\r
    </choose>\r
  </macro>\r
  <macro name="container1-title-serial">\r
    <group delimiter=", ">\r
      <text font-style="italic" text-case="title" variable="volume-title"/>\r
      <group delimiter=" ">\r
        <choose>\r
          <!-- Journal special issues and supplements (MLA 7.4) -->\r
          <if match="none" variable="container-title"/>\r
          <else-if variable="supplement-number volume-title">\r
            <text term="supplement"/>\r
            <text value="to"/>\r
          </else-if>\r
          <else-if type="periodical" variable="supplement-number title">\r
            <text term="supplement" text-case="capitalize-first"/>\r
            <text value="to"/>\r
          </else-if>\r
          <else-if type="periodical" variable="volume-title">\r
            <text term="special-issue" text-case="capitalize-first"/>\r
            <text value="of"/>\r
          </else-if>\r
          <else-if type="periodical" variable="title">\r
            <text term="special-issue" text-case="capitalize-first"/>\r
            <text value="of"/>\r
          </else-if>\r
          <else-if variable="volume-title">\r
            <text term="special-issue"/>\r
            <text value="of"/>\r
          </else-if>\r
        </choose>\r
        <text font-style="italic" text-case="title" variable="container-title"/>\r
        <text prefix="[" suffix="]" variable="publisher-place"/>\r
      </group>\r
    </group>\r
  </macro>\r
  <macro name="container1-title-monographic">\r
    <choose>\r
      <if variable="container-title part-title">\r
        <text font-style="italic" text-case="title" variable="part-title"/>\r
      </if>\r
      <else-if variable="container-title volume-title">\r
        <text font-style="italic" text-case="title" variable="volume-title"/>\r
      </else-if>\r
      <else>\r
        <text font-style="italic" text-case="title" variable="container-title"/>\r
      </else>\r
    </choose>\r
  </macro>\r
  <!-- 4.2. Contributor (MLA 5.38-47) -->\r
  <macro name="container1-contributor">\r
    <group delimiter=", ">\r
      <names delimiter=", " variable="container-author">\r
        <label form="verb" suffix=" "/>\r
        <name initialize="false"/>\r
      </names>\r
      <choose>\r
        <if variable="container-title">\r
          <names delimiter=", " variable="editor-translator">\r
            <label form="verb" suffix=" "/>\r
            <name initialize="false"/>\r
          </names>\r
          <names delimiter=", " variable="editor translator">\r
            <label form="verb" suffix=" "/>\r
            <name initialize="false"/>\r
          </names>\r
          <names delimiter=", " variable="director series-creator illustrator host narrator contributor">\r
            <label form="verb" suffix=" "/>\r
            <name initialize="false"/>\r
          </names>\r
        </if>\r
        <else>\r
          <names delimiter=", " variable="editor-translator">\r
            <label form="verb" suffix=" " text-case="capitalize-first"/>\r
            <name initialize="false"/>\r
          </names>\r
          <names delimiter=", " variable="editor translator">\r
            <label form="verb" suffix=" " text-case="capitalize-first"/>\r
            <name initialize="false"/>\r
          </names>\r
          <names delimiter=", " variable="director series-creator illustrator host narrator contributor">\r
            <label form="verb" suffix=" " text-case="capitalize-first"/>\r
            <name initialize="false"/>\r
          </names>\r
        </else>\r
      </choose>\r
    </group>\r
  </macro>\r
  <!-- 4.3. Version (MLA 5.48-50) -->\r
  <macro name="container1-version">\r
    <group delimiter=", ">\r
      <text macro="label-edition-capitalized"/>\r
      <choose>\r
        <if variable="edition">\r
          <text macro="label-version"/>\r
        </if>\r
        <else>\r
          <text macro="label-version-capitalized"/>\r
        </else>\r
      </choose>\r
    </group>\r
  </macro>\r
  <!-- 4.4. Number (MLA 5.51-53) -->\r
  <macro name="container1-number">\r
    <group delimiter=", ">\r
      <choose>\r
        <!-- \`collection-title\` is for any serial with multiple series (e.g. 'second series') -->\r
        <if match="any" type="article-journal article-magazine article-newspaper periodical post-weblog review review-book">\r
          <!-- serial types -->\r
          <text variable="collection-title"/>\r
          <text macro="label-volume"/>\r
        </if>\r
        <else-if match="any" variable="collection-editor compiler editor editorial-director">\r
          <!-- monographic types -->\r
          <text macro="label-volume"/>\r
        </else-if>\r
        <else-if match="any" type="interview paper-conference">\r
          <!-- serial types -->\r
          <text variable="collection-title"/>\r
          <text macro="label-volume"/>\r
        </else-if>\r
        <!-- in monographic types, lowercase with a preceding element -->\r
        <else-if match="any" variable="part-title volume-title">\r
          <!-- monographic types -->\r
          <text macro="label-volume"/>\r
        </else-if>\r
        <else-if match="any" variable="edition container-title">\r
          <text macro="label-volume"/>\r
        </else-if>\r
        <!--other contributors preceding the volume-->\r
        <else-if variable="author">\r
          <choose>\r
            <if match="any" variable="container-author contributor director editor editor-translator illustrator interviewer translator">\r
              <text macro="label-volume"/>\r
            </if>\r
          </choose>\r
        </else-if>\r
        <else>\r
          <text macro="label-volume-capitalized"/>\r
        </else>\r
      </choose>\r
      <text macro="label-issue"/>\r
      <text macro="label-supplement-number"/>\r
      <group delimiter=" ">\r
        <choose>\r
          <if is-numeric="number" type="broadcast" variable="genre">\r
            <text variable="genre"/>\r
            <text variable="number"/>\r
          </if>\r
          <else-if is-numeric="number" type="broadcast">\r
            <text value="episode"/>\r
            <text variable="number"/>\r
          </else-if>\r
          <else-if variable="number">\r
            <text variable="genre"/>\r
            <text macro="label-number"/>\r
          </else-if>\r
        </choose>\r
      </group>\r
    </group>\r
  </macro>\r
  <!-- 4.5. Publisher (MLA 5.54-67) -->\r
  <macro name="container1-publisher">\r
    <choose>\r
      <if type="thesis"/>\r
      <!-- omit serial types -->\r
      <else-if match="any" type="article-journal article-magazine article-newspaper periodical post-weblog review review-book"/>\r
      <else-if match="any" variable="collection-editor compiler editor editorial-director">\r
        <!-- monographic types -->\r
        <text macro="container1-publisher-or-place"/>\r
      </else-if>\r
      <!-- omit serial types -->\r
      <else-if match="any" type="interview paper-conference"/>\r
      <else>\r
        <!-- monographic types -->\r
        <text macro="container1-publisher-or-place"/>\r
      </else>\r
    </choose>\r
  </macro>\r
  <macro name="container1-publisher-or-place">\r
    <choose>\r
      <if variable="publisher">\r
        <text variable="publisher"/>\r
      </if>\r
      <else>\r
        <!-- use place of publication as fallback (cf. MLA 5.67) -->\r
        <text variable="publisher-place"/>\r
      </else>\r
    </choose>\r
  </macro>\r
  <!-- 4.6. Publication Date (MLA 5.68-83) -->\r
  <macro name="container1-publication-date">\r
    <choose>\r
      <if match="any" type="book chapter motion_picture paper-conference thesis">\r
        <choose>\r
          <if is-uncertain-date="issued">\r
            <date date-parts="year" form="numeric" prefix="[" suffix="?]" variable="issued"/>\r
          </if>\r
          <else>\r
            <date date-parts="year" form="numeric" variable="issued"/>\r
          </else>\r
        </choose>\r
      </if>\r
      <else-if type="article-journal">\r
        <choose>\r
          <if is-uncertain-date="issued">\r
            <date date-parts="year-month" form="text" prefix="[" suffix="?]" variable="issued"/>\r
          </if>\r
          <else>\r
            <date date-parts="year-month" form="text" variable="issued"/>\r
          </else>\r
        </choose>\r
      </else-if>\r
      <else-if type="speech"/>\r
      <else>\r
        <choose>\r
          <if is-uncertain-date="issued">\r
            <group delimiter=" ">\r
              <text term="circa" text-case="capitalize-first"/>\r
              <date form="text" variable="issued"/>\r
            </group>\r
          </if>\r
          <else>\r
            <date form="text" variable="issued"/>\r
          </else>\r
        </choose>\r
      </else>\r
    </choose>\r
  </macro>\r
  <!-- 4.7. Location (MLA 5.84-99) -->\r
  <macro name="container1-location">\r
    <!-- location of a physical object or event (MLA 5.99) -->\r
    <group delimiter=", ">\r
      <choose>\r
        <!-- serials cannot be part of an event -->\r
        <if match="any" type="article-journal article-magazine article-newspaper periodical post-weblog review review-book"/>\r
        <!-- \`event-date\` supplies date of composition for letters, handled in \`supplemental-original-date\` -->\r
        <else-if type="personal_communication"/>\r
        <else-if type="paper-conference">\r
          <choose>\r
            <if match="none" variable="collection-editor compiler editor editorial-director issue page supplement-number volume">\r
              <!-- Don't print event info for conference papers published in a proceedings volume -->\r
              <text macro="container1-location-event"/>\r
            </if>\r
          </choose>\r
        </else-if>\r
        <else>\r
          <!-- For other item types, print event info even if published (e.g. collection catalogs, performance programs). -->\r
          <text macro="container1-location-event"/>\r
        </else>\r
      </choose>\r
      <text variable="archive"/>\r
      <text variable="archive-place"/>\r
      <text variable="archive_collection"/>\r
      <text variable="archive_location"/>\r
      <text macro="label-page"/>\r
      <choose>\r
        <if match="none" variable="source">\r
          <text macro="container1-location-URI"/>\r
        </if>\r
      </choose>\r
    </group>\r
  </macro>\r
  <macro name="container1-location-event">\r
    <group delimiter=", ">\r
      <choose>\r
        <if match="any" variable="event event-date event-title">\r
          <!-- TODO: We expect \`event-title\` to be used, but processors and applications may not be updated yet. This macro ensures that either \`event\` or \`event-title\` can be accepted. Remove if processor logic and application adoption can handle this. -->\r
          <choose>\r
            <if variable="event-title">\r
              <text text-case="capitalize-first" variable="event-title"/>\r
            </if>\r
            <else>\r
              <text text-case="capitalize-first" variable="event"/>\r
            </else>\r
          </choose>\r
          <choose>\r
            <if is-uncertain-date="event-date">\r
              <date form="text" prefix="[" suffix="?]" variable="event-date"/>\r
            </if>\r
            <else>\r
              <date form="text" variable="event-date"/>\r
            </else>\r
          </choose>\r
          <text variable="event-place"/>\r
        </if>\r
      </choose>\r
    </group>\r
  </macro>\r
  <macro name="container1-location-URI">\r
    <choose>\r
      <if variable="DOI">\r
        <text prefix="https://doi.org/" variable="DOI"/>\r
      </if>\r
      <else>\r
        <text variable="URL"/>\r
      </else>\r
    </choose>\r
  </macro>\r
  <!-- 5. Supplemental Element Between Containers (MLA 5.119) -->\r
  <macro name="supplemental-element-between">\r
    <choose>\r
      <if variable="source">\r
        <text macro="supplemental-element-movable"/>\r
      </if>\r
    </choose>\r
  </macro>\r
  <!-- 6. Container 2 (MLA 5.102) -->\r
  <macro name="container2">\r
    <group delimiter=", ">\r
      <choose>\r
        <if match="none" variable="source"/>\r
        <else-if match="any" variable="DOI URL">\r
          <!-- Title of Container -->\r
          <text font-style="italic" variable="source"/>\r
          <!-- Location -->\r
          <text macro="container1-location-URI"/>\r
        </else-if>\r
      </choose>\r
    </group>\r
  </macro>\r
  <!-- 7. Supplemental Element at End of Entry (MLA 5.110-118) -->\r
  <macro name="supplemental-element-end">\r
    <group delimiter=", ">\r
      <text macro="supplemental-date-access"/>\r
      <text macro="supplemental-medium"/>\r
      <choose>\r
        <if variable="source"/>\r
        <else>\r
          <text macro="supplemental-element-movable"/>\r
        </else>\r
      </choose>\r
    </group>\r
  </macro>\r
  <macro name="supplemental-element-movable">\r
    <!-- information relevant only to one container appears either in \`supplemental-element-between\` or \`supplemental-element-end\` depending on the presence of \`source\` -->\r
    <group delimiter=", ">\r
      <choose>\r
        <if match="any" type="article-journal article-magazine article-newspaper periodical post-weblog review review-book">\r
          <!-- serial types -->\r
          <text macro="supplemental-columns-sections"/>\r
        </if>\r
        <else-if match="any" type="interview paper-conference">\r
          <choose>\r
            <if match="any" variable="collection-editor compiler editor editorial-director">\r
              <!-- monographic types -->\r
              <text macro="supplemental-dissertations-theses"/>\r
              <text macro="supplemental-publication-history"/>\r
              <text macro="supplemental-book-series"/>\r
              <text macro="supplemental-multivolume-works"/>\r
            </if>\r
            <else>\r
              <!-- serial types -->\r
              <text macro="supplemental-columns-sections"/>\r
            </else>\r
          </choose>\r
        </else-if>\r
        <else>\r
          <!-- monographic types -->\r
          <text macro="supplemental-dissertations-theses"/>\r
          <text macro="supplemental-publication-history"/>\r
          <text macro="supplemental-book-series"/>\r
          <text macro="supplemental-multivolume-works"/>\r
        </else>\r
      </choose>\r
    </group>\r
  </macro>\r
  <!-- 7.1. Date of access (MLA 5.111) -->\r
  <macro name="supplemental-date-access">\r
    <choose>\r
      <if match="none" variable="issued">\r
        <group delimiter=" ">\r
          <text term="accessed" text-case="capitalize-first"/>\r
          <date form="text" variable="accessed"/>\r
        </group>\r
      </if>\r
    </choose>\r
  </macro>\r
  <!-- 7.2. Medium of publication (MLA 5.112) -->\r
  <macro name="supplemental-medium">\r
    <text text-case="capitalize-first" variable="medium"/>\r
  </macro>\r
  <!-- 7.3. Dissertations and theses (MLA 5.113) -->\r
  <macro name="supplemental-dissertations-theses">\r
    <choose>\r
      <if type="thesis">\r
        <group delimiter=", ">\r
          <text variable="publisher"/>\r
          <text variable="genre"/>\r
        </group>\r
      </if>\r
    </choose>\r
  </macro>\r
  <!-- 7.4. Publication history (MLA 5.114) -->\r
  <macro name="supplemental-publication-history">\r
    <group delimiter=" ">\r
      <choose>\r
        <if match="any" variable="original-publisher original-publisher-place original-title">\r
          <text term="original-work-published" text-case="capitalize-first"/>\r
        </if>\r
      </choose>\r
      <group delimiter=", ">\r
        <group delimiter=" ">\r
          <text value="as"/>\r
          <text font-style="italic" text-case="title" variable="original-title"/>\r
        </group>\r
        <choose>\r
          <if match="any" variable="original-publisher original-publisher-place">\r
            <choose>\r
              <if variable="original-publisher">\r
                <group delimiter=" ">\r
                  <choose>\r
                    <if match="none" variable="original-title">\r
                      <text term="by"/>\r
                    </if>\r
                  </choose>\r
                  <text variable="original-publisher"/>\r
                </group>\r
              </if>\r
              <else>\r
                <text variable="original-publisher-place"/>\r
              </else>\r
            </choose>\r
            <choose>\r
              <if is-uncertain-date="original-date">\r
                <date date-parts="year" form="numeric" prefix="[" suffix="?]" variable="original-date"/>\r
              </if>\r
              <else>\r
                <date date-parts="year" form="numeric" variable="original-date"/>\r
              </else>\r
            </choose>\r
          </if>\r
        </choose>\r
      </group>\r
    </group>\r
  </macro>\r
  <!-- 7.5. Book series (MLA 5.115) -->\r
  <macro name="supplemental-book-series">\r
    <group delimiter=", ">\r
      <choose>\r
        <if is-numeric="collection-number" variable="collection-title">\r
          <group delimiter=" ">\r
            <text text-case="title" variable="collection-title"/>\r
            <text variable="collection-number"/>\r
          </group>\r
        </if>\r
        <else-if variable="collection-title">\r
          <text text-case="title" variable="collection-title"/>\r
          <text variable="collection-number"/>\r
        </else-if>\r
      </choose>\r
    </group>\r
  </macro>\r
  <!-- 7.6. Columns, sections, and other recurring titled features (MLA 5.116) -->\r
  <macro name="supplemental-columns-sections">\r
    <text text-case="title" variable="section"/>\r
  </macro>\r
  <!-- 7.7. Multivolume works (MLA 5.117) -->\r
  <macro name="supplemental-multivolume-works">\r
    <group delimiter=", ">\r
      <choose>\r
        <if variable="part-number part-title volume volume-title">\r
          <!-- part and title with individual titles -->\r
          <group delimiter=" ">\r
            <text macro="label-part-number-capitalized"/>\r
            <text value="of"/>\r
            <text font-style="italic" text-case="title" variable="volume-title"/>\r
          </group>\r
          <group delimiter=" ">\r
            <text macro="label-volume"/>\r
            <text value="of"/>\r
            <group delimiter=", ">\r
              <choose>\r
                <if variable="container-title">\r
                  <text font-style="italic" text-case="title" variable="container-title"/>\r
                </if>\r
                <else>\r
                  <text macro="title-primary"/>\r
                </else>\r
              </choose>\r
              <names variable="collection-editor">\r
                <name initialize="false"/>\r
                <label prefix=", "/>\r
              </names>\r
            </group>\r
          </group>\r
        </if>\r
        <else-if match="any" variable="part-title volume-title">\r
          <group delimiter=" ">\r
            <choose>\r
              <if variable="part-number volume">\r
                <group delimiter=", ">\r
                  <text macro="label-volume-capitalized"/>\r
                  <text macro="label-part-number"/>\r
                  <text value="of"/>\r
                </group>\r
              </if>\r
              <else-if variable="part-number">\r
                <text macro="label-part-number-capitalized"/>\r
                <text value="of"/>\r
              </else-if>\r
              <else-if variable="volume">\r
                <text macro="label-volume-capitalized"/>\r
                <text value="of"/>\r
              </else-if>\r
            </choose>\r
            <group delimiter=", ">\r
              <choose>\r
                <if variable="container-title">\r
                  <text font-style="italic" text-case="title" variable="container-title"/>\r
                </if>\r
                <else>\r
                  <text macro="title-primary"/>\r
                </else>\r
              </choose>\r
              <names variable="collection-editor">\r
                <name initialize="false"/>\r
                <label prefix=", "/>\r
              </names>\r
            </group>\r
          </group>\r
        </else-if>\r
        <!-- numbers without a volume title appear in \`container1-number\` -->\r
      </choose>\r
      <choose>\r
        <if match="none" variable="volume">\r
          <text macro="label-number-of-volumes"/>\r
        </if>\r
      </choose>\r
      <!-- TODO: provide container date here when available -->\r
    </group>\r
  </macro>\r
  <citation disambiguate-add-givenname="true" disambiguate-add-names="true" et-al-min="3" et-al-use-first="1">\r
    <layout delimiter="; " prefix="(" suffix=")">\r
      <choose>\r
        <if locator="line page timestamp" match="any">\r
          <group delimiter=" ">\r
            <text macro="author-short"/>\r
            <text variable="locator"/>\r
          </group>\r
        </if>\r
        <else>\r
          <group delimiter=", ">\r
            <text macro="author-short"/>\r
            <text macro="label-locator"/>\r
          </group>\r
        </else>\r
      </choose>\r
    </layout>\r
  </citation>\r
  <bibliography entry-spacing="0" et-al-min="3" et-al-use-first="1" hanging-indent="true" line-spacing="2" subsequent-author-substitute="&#8212;&#8212;&#8212;">\r
    <sort>\r
      <key macro="author"/>\r
      <key macro="title"/>\r
      <key macro="supplemental-element-after-title"/>\r
      <key macro="container1"/>\r
      <key macro="supplemental-element-between"/>\r
      <key macro="container2"/>\r
      <key macro="supplemental-element-end"/>\r
    </sort>\r
    <layout suffix=".">\r
      <group delimiter=". ">\r
        <text macro="author"/>\r
        <text macro="title"/>\r
        <text macro="supplemental-element-after-title"/>\r
        <text macro="container1"/>\r
        <text macro="supplemental-element-between"/>\r
        <text macro="container2"/>\r
        <text macro="supplemental-element-end"/>\r
      </group>\r
    </layout>\r
  </bibliography>\r
</style>\r
`;export{e as default};
